<?php namespace App\Services;
class ContentSanitizer { public function sanitize(string $html):array {$removed=[];$html=preg_replace_callback('/<script\b[^>]*>.*?<\/script>/is',function($m)use(&$removed){$removed[]='script';return '';},$html);$html=preg_replace_callback('/<iframe\b([^>]*)>.*?<\/iframe>/is',function($m)use(&$removed){if(preg_match('/src=["\']https:\/\/(www\.)?(youtube\.com|youtu\.be|vimeo\.com)\//i',$m[1]))return $m[0];$removed[]='iframe';return '';},$html);$html=preg_replace('/<style\b[^>]*>.*?<\/style>/is','',$html);return ['html'=>trim($html),'removed'=>$removed];}}
